package dev.jco.upgrades.client;
import com.mojang.blaze3d.vertex.VertexConsumer;
final class FadeVertex implements VertexConsumer {private final VertexConsumer out;private final float alpha;private float scroll;FadeVertex(VertexConsumer out,float alpha){this.out=out;this.alpha=alpha;this.scroll=(System.nanoTime()%120000000000L)/120000000000F;}public VertexConsumer addVertex(float x,float y,float z){out.addVertex(x,y,z);return this;}public VertexConsumer setColor(int r,int g,int b,int a){out.setColor(r,g,b,(int)(a*alpha));return this;}public VertexConsumer setUv(float u,float v){out.setUv(u+scroll,v+scroll*.55F);return this;}public VertexConsumer setUv1(int a,int b){out.setUv1(a,b);return this;}public VertexConsumer setUv2(int a,int b){out.setUv2(a,b);return this;}public VertexConsumer setNormal(float x,float y,float z){out.setNormal(x,y,z);return this;}}
